package com.bank.qa.flaky;

// Simulates a balance that becomes correct after a VARIABLE delay,
// like an async UI update. Fixed sleeps race against this; polling waits.
class AsyncBalance {
    private final long readyAtMillis;
    AsyncBalance(long delayMillis) { this.readyAtMillis = System.currentTimeMillis() + delayMillis; }
    String read() {
        return System.currentTimeMillis() >= readyAtMillis ? "950000" : "1000000"; // stale until ready
    }
}
