package com.bank.qa.flaky;

import java.util.logging.Logger;

// Retries are allowed only as a VISIBLE temporary crutch: every retry is
// logged and counted so a nonzero retry rate is treated as a bug to fix.
class RetryTracker {
    private static final Logger log = Logger.getLogger(RetryTracker.class.getName());
    private int totalRuns = 0, totalRetries = 0;

    boolean runWithTrackedRetries(String name, java.util.function.BooleanSupplier test, int maxRetries) {
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            totalRuns++;
            if (test.getAsBoolean()) {
                if (attempt > 0) log.warning(name + " PASSED only after " + attempt
                    + " retr(ies) — FLAKY, root cause must be fixed");
                return true;
            }
            if (attempt < maxRetries) { totalRetries++; log.warning(name + " retry " + (attempt + 1)); }
        }
        log.severe(name + " FAILED after retries");
        return false;
    }

    double retryRatePct() { return totalRuns == 0 ? 0 : (100.0 * totalRetries / totalRuns); }
}
