package com.bank.qa.flaky;

import java.util.Random;
import java.util.logging.*;

public class FlakyTestDemo {
    private static final Logger log = Logger.getLogger(FlakyTestDemo.class.getName());
    private static final Random RNG = new Random(7);

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new FlakyLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    // BAD: fixed sleep, then read once — flakes when the delay exceeds the sleep.
    static boolean withFixedSleep() {
        AsyncBalance bal = new AsyncBalance(RNG.nextInt(400)); // 0..399ms variable
        try { Thread.sleep(200); } catch (InterruptedException ignored) {}  // hard-coded guess
        return bal.read().equals("950000");
    }

    // GOOD: poll until ready (auto-wait analogue) — stable regardless of delay.
    static boolean withReadinessWait() {
        AsyncBalance bal = new AsyncBalance(RNG.nextInt(400));
        long deadline = System.currentTimeMillis() + 2000; // generous timeout
        while (System.currentTimeMillis() < deadline) {
            if (bal.read().equals("950000")) return true;    // condition-based wait
            try { Thread.sleep(20); } catch (InterruptedException ignored) {}
        }
        return false;
    }

    public static void main(String[] args) {
        log.info("=== Fixed-sleep test over 10 runs (FLAKY) ===");
        int sleepPass = 0;
        for (int i = 0; i < 10; i++) if (withFixedSleep()) sleepPass++;
        log.info("fixed-sleep passed " + sleepPass + "/10 (intermittent = flaky)");

        log.info("=== Readiness-wait test over 10 runs (STABLE) ===");
        int waitPass = 0;
        for (int i = 0; i < 10; i++) if (withReadinessWait()) waitPass++;
        log.info("readiness-wait passed " + waitPass + "/10 (deterministic)");

        log.info("=== Blanket retry makes it 'green' but HIDES the defect ===");
        RetryTracker tracker = new RetryTracker();
        for (int i = 0; i < 10; i++) tracker.runWithTrackedRetries("flaky-transfer",
            FlakyTestDemo::withFixedSleep, 3);
        log.info(String.format("Retry rate = %.0f%% (nonzero = defect to fix, not a steady state)",
            tracker.retryRatePct()));
        log.info("Lesson: retries bought green but the real fix was the readiness wait.");
    }
}

